package com.bank.compliance.service;

import com.bank.compliance.model.Employee;
import java.util.List;
import java.util.logging.Logger;
import java.util.stream.Collectors;

public class ComplianceService {
    private static final Logger log = Logger.getLogger(ComplianceService.class.getName());
    private static final String GMAIL = "@gmail.com";

    public List<Employee> gmailUsers(List<Employee> employees) {
        log.info(() -> "Scanning " + employees.size() + " employees for gmail.com addresses");
        return employees.stream()
                // Null guard, lower-case for case-insensitive domain match, then suffix test.
                .filter(e -> e.getEmail() != null
                          && e.getEmail().toLowerCase().endsWith(GMAIL))
                .collect(Collectors.toList());
    }
}
